@Service
public class OrderService {
    private final JdbcTemplate jdbcTemplate;

    public OrderService(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate; // uses pooled connections automatically
    }

    public List<Order> findRecentOrders() {
        // Connection borrowed from pool, used, returned automatically
        return jdbcTemplate.query(
            "SELECT id, customer_name, total FROM orders WHERE created_at > NOW() - INTERVAL '7 days'",
            (rs, rowNum) -> new Order(rs.getLong("id"), rs.getString("customer_name"), rs.getBigDecimal("total"))
        );
    }
}

