@Service
public class ReportService {
    private final DataSource dataSource;

    public ReportService(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public void generateReport() {
        // Correct: try-with-resources ensures connection is always returned
        try (var connection = dataSource.getConnection();
             var statement = connection.prepareStatement("SELECT * FROM orders WHERE status = ?")) {

            statement.setString(1, "COMPLETED");
            var resultSet = statement.executeQuery();

            while (resultSet.next()) {
                // Process results
            }
        } catch (SQLException e) {
            // If pool exhausted, this catches the timeout exception
            if (e.getMessage().contains("Connection is not available")) {
                throw new RuntimeException("Database pool exhausted - check pool size and connection leaks", e);
            }
            throw new RuntimeException("Database error", e);
        }
    }
}

// WRONG: Connection leak if exception occurs before close
public void badExample(DataSource dataSource) throws SQLException {
    Connection conn = dataSource.getConnection();
    PreparedStatement stmt = conn.prepareStatement("SELECT * FROM customers");
    ResultSet rs = stmt.executeQuery();
    // If exception here, connection never closed
    processResults(rs);
    rs.close();
    stmt.close();
    conn.close(); // Never reached if exception above
}

// CORRECT: Try-with-resources guarantees closure
public List<Customer> safeExample(DataSource dataSource) {
    var customers = new ArrayList<Customer>();
    try (var conn = dataSource.getConnection();
         var stmt = conn.prepareStatement("SELECT id, name FROM customers");
         var rs = stmt.executeQuery()) {

        while (rs.next()) {
            customers.add(new Customer(rs.getLong("id"), rs.getString("name")));
        }
    } catch (SQLException e) {
        throw new RuntimeException("Failed to fetch customers", e);
    }
    return customers; // Connection always returned to pool
}

// BEST: Use Spring JdbcTemplate - no manual connection management
@Repository
public class CustomerRepository {
    private final JdbcTemplate jdbcTemplate;

    public List<Customer> findAll() {
        return jdbcTemplate.query(
            "SELECT id, name FROM customers",
            (rs, rowNum) -> new Customer(rs.getLong("id"), rs.getString("name"))
        ); // Spring closes connection automatically
    }
}

