@RestController
public class OrderController {
    private final DataSource dataSource;
    private final MeterRegistry meterRegistry;

    public OrderController(DataSource dataSource, MeterRegistry meterRegistry) {
        this.dataSource = dataSource;
        this.meterRegistry = meterRegistry;
    }

    @GetMapping("/orders/{id}")
    public ResponseEntity<Order> getOrder(@PathVariable Long id) {
        try (var conn = dataSource.getConnection();
             var stmt = conn.prepareStatement("SELECT id, customer_name, total FROM orders WHERE id = ?")) {

            stmt.setLong(1, id);
            var rs = stmt.executeQuery();

            if (rs.next()) {
                var order = new Order(rs.getLong("id"), rs.getString("customer_name"), rs.getBigDecimal("total"));
                return ResponseEntity.ok(order);
            }
            return ResponseEntity.notFound().build();

        } catch (SQLException e) {
            if (e.getMessage().contains("Connection is not available")) {
                // Pool exhausted - log and alert
                meterRegistry.counter("database.pool.exhaustion").increment();
                return ResponseEntity.status(503).build(); // Service unavailable
            }
            return ResponseEntity.status(500).build();
        }
    }
}

